alter table public.companies enable row level security;alter table public.profiles enable row level security;create policy "profiles own" on public.profiles for select to authenticated using(user_id=auth.uid());create policy "companies current" on public.companies for select to authenticated using(id=public.current_company_id());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['clients','part_numbers','operations','machines','part_operations','part_operation_machines','personnel','shifts','defect_catalog','downtime_reasons','production_runs','production_records','quality_records','downtime_records','company_settings','dashboard_metric_settings','audit_logs'] LOOP EXECUTE format('alter table public.%I enable row level security',t);EXECUTE format('create policy %I on public.%I for all to authenticated using(company_id=public.current_company_id()) with check(company_id=public.current_company_id())',t||'_tenant',t); END LOOP; END $$;
alter table public.user_preferences enable row level security;create policy "preferences own" on public.user_preferences for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
